package com.abdallataha.mishwar;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.net.Uri;import android.graphics.Color;import android.view.Gravity;import android.widget.LinearLayout;import android.widget.TextView;import android.widget.Button;
/** Browser-backed app entry point with explicit, guarded fallbacks. No incoming URI is trusted. */
public class MainActivity extends Activity {
 @Override public void onCreate(Bundle saved){super.onCreate(saved);Uri data=getIntent().getData();if(data!=null&&"mishwar-app".equals(data.getScheme())&&"share".equals(data.getHost())){shareApk();return;}openApp();}
 private void shareApk(){try{Uri uri=Uri.parse("content://"+getPackageName()+".apkshare/application.apk");Intent send=new Intent(Intent.ACTION_SEND);send.setType("application/vnd.android.package-archive");send.putExtra(Intent.EXTRA_STREAM,uri);send.setClipData(android.content.ClipData.newUri(getContentResolver(),"Mishwar APK",uri));send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(send,"مشاركة تطبيق مشوار"));finish();}catch(RuntimeException e){showFallback(getString(R.string.launch_url));}}
 private void openApp(){String url=getString(R.string.launch_url);boolean opened=LaunchPolicy.open(url,new LaunchPolicy.Opener(){
  public void customTab(String address){Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse(address));Bundle extra=new Bundle();extra.putBinder("android.support.customtabs.extra.SESSION",null);extra.putInt("android.support.customtabs.extra.TOOLBAR_COLOR",Color.rgb(8,51,68));extra.putInt("android.support.customtabs.extra.TITLE_VISIBILITY",1);i.putExtras(extra);i.addCategory(Intent.CATEGORY_BROWSABLE);startActivity(i);}
  public void browser(String address){Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse(address));i.addCategory(Intent.CATEGORY_BROWSABLE);startActivity(i);}
 });if(opened){finish();return;}showFallback(url);}
 private void showFallback(String url){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);int pad=(int)(24*getResources().getDisplayMetrics().density);box.setPadding(pad,pad,pad,pad);box.setBackgroundColor(Color.WHITE);TextView title=new TextView(this);title.setText(getString(R.string.app_name));title.setTextSize(27);title.setTextColor(Color.rgb(8,51,68));title.setGravity(Gravity.CENTER);box.addView(title);TextView message=new TextView(this);message.setText("تعذر فتح المتصفح. تأكد من وجود متصفح محدث مثل Chrome ثم أعد المحاولة.\n\n"+url);message.setTextSize(16);message.setPadding(0,pad,0,pad);message.setGravity(Gravity.CENTER);box.addView(message);Button retry=new Button(this);retry.setText("إعادة المحاولة");retry.setOnClickListener(v->openApp());box.addView(retry);Button back=new Button(this);back.setText("رجوع");back.setOnClickListener(v->finish());box.addView(back);setContentView(box);}
}
